:root{--bg:#08090a;--fg:#e9e7e2;--accent:#b7a17e;--mono:"DM Mono",monospace;--sans:"Manrope",Arial,sans-serif;
  --row:25svh;--W:300svh;--L:91.25svh;--R:117.5svh} /* 2×L + R = W */
*{box-sizing:border-box}
html,body{width:100%;height:100%;margin:0;overflow:hidden;background:var(--bg);color:var(--fg);font-family:var(--sans);-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
button{font:inherit;color:inherit}
.site-header{position:fixed;z-index:50;left:0;right:0;top:0;height:58px;padding:0 2.5vw;display:flex;align-items:center;justify-content:space-between;pointer-events:none;background:linear-gradient(180deg,rgba(5,6,7,.78),rgba(5,6,7,.12) 78%,transparent)}
.wordmark,.main-nav{pointer-events:auto}
.wordmark{font-size:14px;font-weight:700;letter-spacing:-.09em;text-shadow:0 1px 10px #000}
.wordmark span{font:7px var(--mono);vertical-align:top;margin-left:3px;letter-spacing:0}
.main-nav{display:flex;align-items:center;gap:clamp(7px,1vw,14px)}
.main-nav button{min-height:40px;padding:10px 13px;border:1px solid rgba(235,233,226,.25);border-radius:2px;background:rgba(8,9,10,.48);cursor:pointer;font:10px var(--mono);letter-spacing:.12em;color:rgba(245,243,236,.94);text-shadow:0 1px 8px #000;transition:color .2s,border-color .2s,background .2s}
.main-nav button:hover,.main-nav button:focus-visible{color:var(--accent);border-color:rgba(183,161,126,.8);background:rgba(8,9,10,.82)}
.main-nav button:focus-visible{outline:1px solid var(--accent);outline-offset:3px}

/* World: three identical runs; script.js jumps between them for the endless loop */
.world-viewport{position:fixed;inset:0;height:100svh;overflow-x:auto;overflow-y:hidden;overscroll-behavior-x:contain;scrollbar-width:none;touch-action:pan-x pan-y;cursor:grab;outline:none}
.world-viewport::-webkit-scrollbar{display:none}
.world-viewport.is-dragging{cursor:grabbing}
.world-track{display:flex;height:100svh;width:max-content}

/* Tiles: width comes from flex-grow = aspect ratio (set in script.js) */
.tile{position:relative;height:100%;min-width:0;overflow:hidden;background:#171a1c;isolation:isolate;cursor:pointer;color:var(--fg);box-shadow:inset 0 0 0 1.5px var(--bg)}
.tile-media{position:absolute;inset:0;overflow:hidden;background:linear-gradient(140deg,#242a2d,#0c0e10 78%)}
.tile-media::after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(0deg,rgba(0,0,0,.68),transparent 42%)}
.tile-media img,.tile-media video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .7s cubic-bezier(.2,.7,.2,1),opacity .25s}
.tile-media .tile-poster{object-position:50% 50%;transform:none}
.tile-media video{opacity:0}
.tile:hover .tile-media img{transform:none}
.tile.is-active .tile-media video{opacity:1}
.placeholder-mark{position:absolute;inset:0;display:grid;place-items:center;color:rgba(255,255,255,.105);font-size:clamp(40px,7vh,84px);font-weight:500;letter-spacing:-.12em}
.tile-meta{position:absolute;z-index:2;left:14px;right:14px;bottom:12px;font-size:clamp(11px,1vw,15px);font-weight:500;letter-spacing:-.045em;line-height:1.2;text-shadow:0 1px 12px #000}

/* Showreel: 2.35:1, 50svh high, same geometry for hover and click */
.reel-tile{flex:0 0 var(--R);width:var(--R);height:100%;background:#090a0b}
.reel-poster{position:absolute;z-index:1;inset:0;display:block;width:100%;height:100%;object-fit:cover;object-position:50% 50%;transition:opacity .32s ease,transform .7s cubic-bezier(.2,.7,.2,1)}
.reel-tile.is-playing .reel-poster{opacity:0}
.reel-frame{position:absolute;z-index:4;inset:0;width:100%;height:100%;border:0;opacity:0;pointer-events:none}
.reel-tile.is-playing .reel-frame{opacity:1}
.reel-tile.is-full .reel-frame{pointer-events:auto}
.reel-invite{position:absolute;z-index:6;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px;pointer-events:none;transition:opacity .2s}
.reel-play{width:44px;height:44px;border:1px solid rgba(255,255,255,.65);border-radius:50%;display:grid;place-items:center;font-size:12px;padding-left:2px}
.reel-label{font:7px var(--mono);letter-spacing:.18em;color:#d6d2c8}
.reel-tile.is-playing .reel-invite{opacity:0}

/* About / Right now / Contact: text panel takes the same slot as the reel */
.info-copy{flex:0 0 var(--R);width:var(--R);height:100%;padding:clamp(20px,3vw,56px);display:flex;flex-direction:column;justify-content:center;gap:14px;background:#0b0c0e;overflow:hidden}
.info-copy{position:relative;isolation:isolate}
.info-backdrop{position:absolute;z-index:0;inset:0;overflow:hidden;background:#08090a;pointer-events:none}
.info-backdrop::before{content:"";position:absolute;inset:0;opacity:.25;background-repeat:no-repeat;background-position:center;background-size:cover}
.info-copy--about .info-backdrop::before{
  background-image:url("data:image/webp;base64,"),url("data:image/webp;base64,");
  background-size:50% 100%,50% 100%;
  background-position:left center,right center;
}
.info-copy--rightnow .info-backdrop::before{
  background-image:url("data:image/webp;base64,"),url("data:image/webp;base64,");
  background-size:50% 100%,50% 100%;
  background-position:left center,right center;
}
.info-copy--contact .info-backdrop::before{
  background-image:url("data:image/webp;base64,");
  background-size:cover;
  background-position:center;
}
.info-backdrop-shade{position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,9,10,.20),rgba(8,9,10,.34));pointer-events:none}
.info-copy>:not(.info-backdrop){position:relative;z-index:1}
.info-copy h1,.info-copy h2{font-size:clamp(36px,4.6vw,76px);line-height:.9;margin:0;letter-spacing:-.04em;font-weight:600}
.info-copy h1 span,.info-copy h2 span{color:var(--accent)}
.info-copy h3{margin:0;font-size:clamp(18px,2vw,30px);letter-spacing:-.03em}
.info-copy p{margin:0 0 8px;font-size:clamp(11px,.95vw,15px);line-height:1.55;color:#bdbbb5;max-width:60ch}
.info-copy .info-lead{color:var(--fg);font-size:clamp(13px,1.2vw,18px)}
.kicker,.current-meta,.contact-location{font:8px var(--mono);letter-spacing:.16em;color:var(--accent)}
.contact-email{font-size:clamp(18px,2.2vw,34px);font-weight:600;letter-spacing:-.04em}
.contact-email:hover{color:var(--accent)}

.hover-note{position:fixed;z-index:60;left:2.5vw;bottom:2.5vh;max-width:320px;padding:12px 14px;background:rgba(8,9,10,.86);border-left:2px solid var(--accent);opacity:0;transform:translateY(6px);transition:.3s;pointer-events:none}
.hover-note.visible{opacity:1;transform:none}
.hover-note span{font:7px var(--mono);letter-spacing:.16em;color:var(--accent)}
.hover-note p{margin:6px 0 0;font-size:13px}

/* Placeholder tones: varied so the wall reads as a mosaic until real stills are added */
.placeholder-mark{color:rgba(255,255,255,.2)}

/* Continuous-run layout: rows are separate strips, middle layer holds blocks + panels */

/* v3: continuous rows, 2- or 3-row middle layer, 3px gutters, ragged info holes */
.world-run{display:flex;flex-direction:column;flex:0 0 var(--T);width:var(--T);height:100svh}
.mrow{display:flex;flex:0 0 var(--h,25svh);height:var(--h,25svh);width:100%}
/* Tile separators use an inset shadow; no texture overlays are applied. */

/* v4: layers of block trees, stair-stepped info holes, hover dimming */
:root{--T:2400svh;--R:112.8svh}
.strip{width:var(--T)}
.layer{display:flex;flex:0 0 var(--h);height:var(--h)}
.mid{display:flex;flex:0 0 48svh;height:48svh;width:var(--T)}
.mseg{display:flex;flex:0 0 auto;height:48svh}
.cx{display:flex;min-width:0;min-height:0}
.cx.row{flex-direction:row}
.cx.col{flex-direction:column}
.island{position:relative;flex:0 0 auto;height:48svh}
.iside{position:absolute;top:0;height:100%;display:flex;flex-direction:column}
.iside.l{left:0}
.iside.r{right:0;align-items:flex-end}
.iside .mrow{width:auto}
.island .info-copy{position:absolute;left:58svh;top:0;width:100svh;height:48svh;flex:none;padding:2svh 0;background:none;z-index:2}
.island .info-copy h1,.island .info-copy h2{font-size:clamp(28px,3.6vw,60px)}
/* hover: after a moment the other tiles fade slowly darker; they recover quickly */
.tile{transition:filter .5s ease}
body.dim .tile:not(.is-active){filter:brightness(.3);transition:filter 1.8s ease}
/* Placeholder tones (random per tile) until real stills are added */
.tile[style*="--t:0;"] .tile-media{background:linear-gradient(140deg,#3d5560,#101a1f 85%)}
.tile[style*="--t:1;"] .tile-media{background:linear-gradient(140deg,#6a5238,#1c140d 85%)}
.tile[style*="--t:2;"] .tile-media{background:linear-gradient(140deg,#5a4561,#171019 85%)}
.tile[style*="--t:3;"] .tile-media{background:linear-gradient(140deg,#445a48,#0f1812 85%)}
.tile[style*="--t:4;"] .tile-media{background:linear-gradient(140deg,#6b655c,#1a1816 85%)}
.tile[style*="--t:5;"] .tile-media{background:linear-gradient(140deg,#34497a,#0c101d 85%)}


/* V26 — hover notes reveal in changing screen positions. */
.hover-note{
  left:auto; right:auto; top:auto; bottom:auto;
  width:min(330px,34vw);
  max-width:calc(100vw - 40px);
  padding:14px 16px 15px;
  background:linear-gradient(120deg,rgba(8,9,10,.88),rgba(8,9,10,.66));
  border-left:1px solid rgba(183,161,126,.8);
  box-shadow:0 12px 38px rgba(0,0,0,.16);
  backdrop-filter:blur(8px);
  opacity:0;
  transform:translate3d(0,10px,0);
  filter:blur(2px);
  transition:opacity .48s ease,transform .58s cubic-bezier(.2,.75,.25,1),filter .58s ease;
}
.hover-note.visible{opacity:1;transform:translate3d(0,0,0);filter:blur(0)}
.hover-note[data-position="top-left"]{left:4vw;top:12vh;bottom:auto;right:auto}
.hover-note[data-position="top-right"]{right:4vw;top:12vh;bottom:auto;left:auto}
.hover-note[data-position="mid-left"]{left:4vw;top:43vh;bottom:auto;right:auto}
.hover-note[data-position="mid-right"]{right:4vw;top:43vh;bottom:auto;left:auto}
.hover-note[data-position="bottom-left"]{left:4vw;bottom:5vh;top:auto;right:auto}
.hover-note[data-position="bottom-right"]{right:4vw;bottom:5vh;top:auto;left:auto}
.hover-note span{display:block;margin-bottom:2px}
.hover-note p{line-height:1.45;letter-spacing:-.015em}
@media (max-width:700px){
  .site-header{height:54px;padding:0 12px}
  .main-nav{gap:5px}
  .main-nav button{min-height:36px;padding:8px 8px;font-size:8px;letter-spacing:.08em}

  .hover-note{width:min(290px,72vw);padding:11px 13px}
  .hover-note[data-position="top-left"],.hover-note[data-position="mid-left"],.hover-note[data-position="bottom-left"]{left:5vw}
  .hover-note[data-position="top-right"],.hover-note[data-position="mid-right"],.hover-note[data-position="bottom-right"]{right:5vw}
}
@media (prefers-reduced-motion:reduce){
  .hover-note{transition:opacity .2s ease}
}


/* V27 — public project videos: thumbnail first, muted preview on hover, full player on click. */
.tile-poster{transition:opacity .32s ease,transform .7s cubic-bezier(.2,.7,.2,1)}
.tile.is-active .tile-poster{opacity:.08;transform:none}
.tile-preview-frame{
  position:absolute;z-index:1;top:50%;left:50%;display:block;
  border:0;max-width:none;max-height:none;background:#050607;
  transform:translate(-50%,-50%);opacity:0;
  transition:opacity .32s ease;pointer-events:none;
}
.tile.is-active .tile-preview-frame{opacity:1}
.tile.is-active .tile-meta{z-index:3}
.tile-media .placeholder-mark{z-index:0}
.project-modal{position:fixed;inset:0;z-index:120;display:none;align-items:center;justify-content:center;padding:5vh 4vw}
.project-modal.open{display:flex}
.project-modal-backdrop{position:absolute;inset:0;background:rgba(2,3,4,.94);backdrop-filter:blur(18px);opacity:0;animation:projectBackdropIn .35s ease forwards}
.project-modal-dialog{position:relative;z-index:1;width:min(92vw,1480px);max-height:90svh;display:flex;flex-direction:column;gap:12px;opacity:0;transform:translateY(14px) scale(.985);animation:projectDialogIn .42s cubic-bezier(.2,.75,.25,1) .04s forwards}
.project-modal-frame{position:relative;width:100%;aspect-ratio:16/9;max-height:80svh;background:#050607;overflow:hidden;box-shadow:0 24px 90px rgba(0,0,0,.38)}
.project-player-frame{position:absolute;inset:0;width:100%;height:100%;border:0;background:#050607}
.instagram-player-frame{background:#0b0c0e}
.project-modal-close{position:absolute;z-index:5;top:-42px;right:0;width:34px;height:34px;border:1px solid rgba(255,255,255,.32);border-radius:50%;background:rgba(8,9,10,.72);font:24px/1 var(--sans);font-weight:300;color:var(--fg);cursor:pointer;display:grid;place-items:center;transition:background .2s,border-color .2s,transform .2s}
.project-modal-close:hover{background:rgba(183,161,126,.22);border-color:var(--accent);transform:rotate(90deg)}
.project-modal-caption{display:flex;align-items:center;justify-content:space-between;gap:16px;color:rgba(235,233,226,.8);font:9px var(--mono);letter-spacing:.13em;text-transform:uppercase}
.project-modal-caption a{color:var(--accent);white-space:nowrap;transition:opacity .2s}
.project-modal-caption a:hover{opacity:.68}
body.player-open{overflow:hidden}
@keyframes projectBackdropIn{to{opacity:1}}
@keyframes projectDialogIn{to{opacity:1;transform:translateY(0) scale(1)}}
@media(max-width:700px){
  .project-modal{padding:7vh 4vw}
  .project-modal-dialog{width:92vw;gap:10px}
  .project-modal-close{top:-40px}
  .project-modal-caption{font-size:8px;letter-spacing:.08em}
}
@media(prefers-reduced-motion:reduce){
  .tile-preview-frame,.tile-poster,.project-modal-backdrop,.project-modal-dialog,.project-modal-close{transition:none;animation:none}
  .project-modal-backdrop,.project-modal-dialog{opacity:1;transform:none}
}
